Rules.InvariantScript:
// Remove the current item from 'Hours Tracking (Hours)'
Remove('Vacations Tracking (Days)', Gallery_Hours.Selected);
UpdateContext({varShowConfirmation:false});

With(
    {
        varStart: StartDatePicker_Date.SelectedDate,
        varEnd: EndDatePicker_Date.SelectedDate,
        varDiff: DateDiff(StartDatePicker_Date.SelectedDate, EndDatePicker_Date.SelectedDate) + 1
    },
    If(
        Or(
            IsBlank(varStart),
            IsBlank(varEnd),
            varDiff <= 0,
            varDiff > 50000
        ),
        0,
        If(
            Leave_Time.Selected.Value <> "Full Day",
            0.5,
            With(
                {
                    varDateRange: ForAll(
                        Sequence(varDiff),
                        varStart + Value - 1
                    )
                },
                CountIf(
                    varDateRange,
                    And(
                        Weekday(Value) in [2, 3, 4, 5, 6],
                        Not(Value in ForAll(colPublic_Holidays, DateValue(CleanDate)))
                    )
                )
            )
        )
    )
)

UpdateIf(
    FlightEntries,
    true,
    {
        DepartureDate: Blank(),
        ArrivalDate: Blank(),
        DepartureLocation: Blank(),
        ArrivalLocation: Blank(),
        Companion: Blank()
    }
);

If(
    Or(
        IsBlank(StartDatePicker_Date.SelectedDate),
        IsBlank(EndDatePicker_Date.SelectedDate),
        StartDatePicker_Date.SelectedDate > EndDatePicker_Date.SelectedDate
    ),
    Notify("Please fill out dates correctly", NotificationType.Error),
    If(
        Year(StartDatePicker_Date.SelectedDate) <> Year(EndDatePicker_Date.SelectedDate),
        Notify("Please submit days for the next year in a separate record", NotificationType.Error),
        If(
            !IsBlank(
                LookUp(
                    'Vacations Tracking (Days)',
                    StartsWith(Employee, Employee_Text.Text) &&
                    StartDate <= EndDatePicker_Date.SelectedDate &&
                    EndDate >= StartDatePicker_Date.SelectedDate &&
                    ApprovalStatus_1 <> "Rejected"
                )
            ),
            Notify("You already have a vacation or sick day recorded for these dates.", NotificationType.Error),
            // Removed the "current year only" restriction:
            // If( Year(StartDatePicker_Date.SelectedDate) = Year(Today()), Select(AddRecord_Button) )
            // Now we just submit when all validations pass:
            Select(AddRecord_Button)
        )
    )
);

Concurrent(
    // 1. Add new record to SharePoint list
    Patch(
        'Vacations Tracking (Days)',
        Defaults('Vacations Tracking (Days)'),
        {
            Title: GUID_Var,
            LOG_ID: GUID_Var,
            Employee: Employee_Text.Text,
            Employee_Name: User().FullName,
            Project: Selected_ProjectID,
            StartDate: StartDatePicker_Date.SelectedDate,
            EndDate: EndDatePicker_Date.SelectedDate,
            Days: If(
                Flight_Checkbox.Value,
                Max(Value('Days_w/o_weekends'.Text)),
                Value('Days_w/o_weekends'.Text)
            ),
            Travel_Days: If(Flight_Checkbox.Value, Value(varFlightEntitlement), Blank()),
            Leave_Time: Leave_Time.Selected.Value,
            Type_of_leave: Input_Comments_1.Text,
            Comments: Input_Comments.Text,
            App_Name: "Dayaway_HR_Vacations",
            ApproverID_1: Approver_Text.Text,
            ApprovalStatus_1: "Pending"
        }
    ),

    // 2. Send email to ApproverID_1
    Office365Outlook.SendEmailV2(
        Approver_Text.Text, // ApproverID_1 email
        Leave_Type.Selected.Value & " Request Submitted",
        "A new " & Leave_Type.Selected.Value & " request has been submitted by " & Employee_Text.Text &
        ". Please review and approve/reject in the DayAway application.<br><br>" &
        "<b>Type of Leave:</b> " & Leave_Type.Selected.Value & "<br>" &
        "<b>Dates:</b> " & Text(StartDatePicker_Date.SelectedDate, "[$-en-US]dd-mmm-yyyy") &
        " to " & Text(EndDatePicker_Date.SelectedDate, "[$-en-US]dd-mmm-yyyy") & "<br>" &
        "<b>Comments:</b> " & Input_Comments.Text,
        {
            IsHtml: true
        }
    )
);

// 3. Notify user
Notify("Hours submitted!", NotificationType.Success, 1000);

// 4. Reset form fields
Set(GUID_Var, GUID());
Reset(StartDatePicker_Date);
Reset(Leave_Time);
Reset(EndDatePicker_Date);
Reset(Input_Comments);
Reset(Flight_Checkbox);
Reset(Leave_Type);
Reset(Leave_Time);

If(
    CountRows(colVacationsUpdates) > 0,
        Patch(
            'Vacations Tracking (Days)',
            ShowColumns(
                colVacationsUpdates,
                ID,
                Employee,
                StartDate,
                EndDate,
                Days,
                Comments,
                ApprovalStatus_1,
                ApprovalStatus_2
            )
        )
    );
    Clear(colVacationsUpdates);
    Notify("Records updated successfully!", NotificationType.Success);
    Refresh('Vacations Tracking (Days)');

//Remove changes
Clear(colVacationsUpdates);

// Refresh the data source
Refresh('Vacations Tracking (Days)');

With(
    {
        sortedRows: SortByColumns(
            Filter(
                'Vacations Tracking (Days)',
                'Created By'.Email = User().Email
            ),
            "EndDate",
            SortOrder.Descending
        ),
        rowCount: CountRows(
            SortByColumns(
                Filter(
                    'Vacations Tracking (Days)',
                    'Created By'.Email = User().Email
                ),
                "EndDate",
                SortOrder.Descending
            )
        )
    },
    If(
        rowCount >= 10,
        446, // Max height if more than 10 rows
        52 + 40 * rowCount
    )
)

// Track changes related to hours table
If(
    IsBlank(
        LookUp(
            colVacationsUpdates,
            ID = ThisItem.ID
        )
    ),
    Collect(
        colVacationsUpdates,
        {
            ID: ThisItem.ID,
            StartDate: DateValue(TextInput_StartDate.Text),
            EndDate: DateValue(TextInput_EndDate.Text),
            Days: Value(TextLabel_Days.Text),
            Comments: TextInput_Comments.Text,
            ApprovalStatus_1: "Pending"
        }
    ),
    UpdateIf(
        colVacationsUpdates,
        ID = ThisItem.ID,
        {
            StartDate: DateValue(TextInput_StartDate.Text),
            EndDate: DateValue(TextInput_EndDate.Text),
            Days: Value(TextLabel_Days.Text),
            Comments: TextInput_Comments.Text,
            ApprovalStatus_1: "Pending"
        }
    )
);

// Track changes related to hours table
If(
    IsBlank(
        LookUp(
            colVacationsUpdates,
            ID = ThisItem.ID
        )
    ),
    Collect(
        colVacationsUpdates,
        {
            ID: ThisItem.ID,
            StartDate: DateValue(TextInput_StartDate.Text),
            EndDate: DateValue(TextInput_EndDate.Text),
            Days: Value(TextLabel_Days.Text),
            Comments: TextInput_Comments.Text,
            ApprovalStatus_1: "Pending"
        }
    ),
    UpdateIf(
        colVacationsUpdates,
        ID = ThisItem.ID,
        {
            StartDate: DateValue(TextInput_StartDate.Text),
            EndDate: DateValue(TextInput_EndDate.Text),
            Days: Value(TextLabel_Days.Text),
            Comments: TextInput_Comments.Text,
            ApprovalStatus_1: "Pending"
        }
    )
);

With(
    {
        varStartText: Text(DateValue(TextInput_StartDate.Text)),
        varEndText: Text(DateValue(TextInput_EndDate.Text))
    },
    If(
        ThisItem.Leave_Time <> "Full Day",
        0.5,
        If(
            Or(
                !IsMatch(varStartText, "^\d{1,2}/\d{1,2}/\d{4}$"),
                !IsMatch(varEndText, "^\d{1,2}/\d{1,2}/\d{4}$"),
                DateDiff(DateValue(varStartText), DateValue(varEndText)) + 1 <= 0,
                DateDiff(DateValue(varStartText), DateValue(varEndText)) + 1 > 50000
            ),
            0,
            With(
                {
                    varStart: DateValue(varStartText),
                    varEnd: DateValue(varEndText),
                    varDiff: DateDiff(DateValue(varStartText), DateValue(varEndText)) + 1
                },
                CountIf(
                    ForAll(
                        Sequence(varDiff),
                        varStart + Value - 1
                    ),
                    And(
                        Weekday(Value) in [2, 3, 4, 5, 6],
                        Not(
                            Value in ForAll(colPublic_Holidays, DateValue(CleanDate))
                        )
                    )
                )
            )
        )
    )
) - ThisItem.Travel_Days

// Track changes related to hours table
If(
    IsBlank(
        LookUp(
            colVacationsUpdates,
            ID = ThisItem.ID
        )
    ),
    Collect(
        colVacationsUpdates,
        {
            ID: ThisItem.ID,
            StartDate: DateValue(TextInput_StartDate.Text),
            EndDate: DateValue(TextInput_EndDate.Text),
            Days: Value(TextLabel_Days.Text),
            Comments: TextInput_Comments.Text,
            ApprovalStatus_1: "Pending"
        }
    ),
    UpdateIf(
        colVacationsUpdates,
        ID = ThisItem.ID,
        {
            StartDate: DateValue(TextInput_StartDate.Text),
            EndDate: DateValue(TextInput_EndDate.Text),
            Days: Value(TextLabel_Days.Text),
            Comments: TextInput_Comments.Text,
            ApprovalStatus_1: "Pending"
        }
    )
);

